// PROJETO SM3 — CURATION QUEUE HARDENED
// Scoring weights come from 14_OS_SCORING v2.
// Structural Vision is consumed whenever present; legacy analyzed media are
// tolerated without manufacturing structural values.
//
// IMPORTANT: a version change alone does NOT re-curate an unchanged project.
// Re-curation occurs for new/un-curated analysis or analysis newer than CURATED_AT.

const mediaRows = $('READ — ANALYZED MEDIA').all().map(i => i.json);
const projectRows = $('READ — PROJECT CURATION STATE').all().map(i => i.json);
const scoringRows = $('READ — SCORING CONFIG').all().map(i => i.json);
const configRows = $('READ — OS CONFIG').all().map(i => i.json);

const CURATION_VERSION = 'SM3_CURATION_V2_STRUCTURAL_CONFIG';

function n(v) {
  const x = Number(v);
  return Number.isFinite(x) ? x : null;
}
function ts(v) {
  const x = Date.parse(String(v || ''));
  return Number.isFinite(x) ? x : 0;
}
function upper(v) {
  return String(v || '').trim().toUpperCase();
}
function parseConfigValue(row) {
  const type = upper(row.TIPO);
  const v = row.VALOR;
  if (type === 'BOOLEAN') return v === true || upper(v) === 'TRUE';
  if (type === 'NUMBER') return Number(v);
  return v;
}

const config = Object.fromEntries(
  configRows
    .filter(r => String(r.CHAVE || '').trim())
    .map(r => [String(r.CHAVE).trim(), parseConfigValue(r)])
);

const scoreRules = scoringRows.filter(r => String(r.VERSAO || '').trim() === '2.0');
const positiveRules = scoreRules.filter(r => upper(r.TIPO) === 'POSITIVO' && Number(r.PESO || 0) > 0);
const actionRules = scoreRules.filter(r => ['BONUS','PENALIDADE'].includes(upper(r.TIPO)));

if (positiveRules.length === 0) {
  throw new Error('CURATION_CONFIG_BLOCK: no positive scoring rules v2 found');
}

const projectState = new Map(
  projectRows
    .filter(r => String(r.ID_PROJETO || '').trim())
    .map(r => [String(r.ID_PROJETO).trim(), r])
);

function dynamicScore(r) {
  let weighted = 0;
  let totalWeight = 0;
  const components = [];

  for (const rule of positiveRules) {
    const field = String(rule.SOURCE_FIELD || '').trim();
    const weight = Number(rule.PESO || 0);
    const value = n(r[field]);

    // Missing legacy fields are excluded, not treated as zero.
    if (!field || value === null) continue;

    const clamped = Math.max(0, Math.min(100, value));
    weighted += clamped * weight;
    totalWeight += weight;
    components.push({criterion: rule.CRITERIO, field, value: clamped, weight});
  }

  if (totalWeight <= 0) {
    throw new Error(`CURATION_SCORE_BLOCK: no usable scoring components for ${r.ID_MIDIA}`);
  }

  let score = weighted / totalWeight;
  const adjustments = [];

  for (const rule of actionRules) {
    const mode = upper(rule.RULE_MODE);
    const amount = Number(rule.PENALIDADE || 0);

    if (mode === 'SELECTED_BONUS' && upper(r.TRIAGEM) === 'SELECIONADO') {
      score += amount;
      adjustments.push({criterion: rule.CRITERIO, amount});
    }

    if (mode === 'DISCARD_PENALTY' && upper(r.TRIAGEM) === 'DESCARTAR') {
      score += amount;
      adjustments.push({criterion: rule.CRITERIO, amount});
    }

    if (mode === 'REDUNDANCY_PENALTY') {
      const hint = upper(r.REDUNDANCY_HINT);
      if (hint.includes('REDUND') || hint.includes('SEMELH') || hint.includes('QUASE DUP')) {
        score += amount;
        adjustments.push({criterion: rule.CRITERIO, amount});
      }
    }
  }

  return {
    score: Math.round(Math.max(0, Math.min(100, score))),
    components,
    adjustments,
    scoring_version: '2.0'
  };
}

const eligibleMedia = mediaRows.filter(r =>
  upper(r.ANALYSIS_STATUS) === 'ANALYZED' &&
  upper(r.STORAGE_STATUS) === 'ONLINE' &&
  String(r.ID_PROJETO || '').trim()
);

const grouped = {};
for (const r of eligibleMedia) {
  const pid = String(r.ID_PROJETO).trim();
  if (!grouped[pid]) grouped[pid] = [];

  const type = upper(r.TIPO);
  const kind = type.includes('VÍDEO') || type.includes('VIDEO') ? 'video' : 'image';
  const scored = dynamicScore(r);
  const structuralAvailable = upper(r.STRUCTURAL_ANALYSIS_VERSION).startsWith('SM3_STRUCTURAL_V');

  grouped[pid].push({
    media_id: r.ID_MIDIA,
    kind,
    analysis_path: kind === 'video'
      ? `/data/media/contact_sheets/${pid}/${r.ID_MIDIA}.jpg`
      : `/data/media/proxies/${pid}/${r.ID_MIDIA}.jpg`,

    stage: r.ANALYSIS_STAGE || '',
    shot_type: r.SHOT_TYPE || '',
    editorial_score: Number(r.EDITORIAL_SCORE || 0),
    technical_score: Number(r.TECHNICAL_SCORE || 0),
    composition_score: Number(r.COMPOSITION_SCORE || 0),
    tattoo_visibility: Number(r.TATTOO_VISIBILITY || 0),
    analysis_confidence: Number(r.ANALYSIS_CONFIDENCE || 0),
    recommended_use: r.USAR_EM || '',
    best_moment: r.MELHOR_TRECHO || '',
    visual_summary: r['CONTEÚDO_VISUAL'] || '',
    redundancy_hint: r.REDUNDANCY_HINT || '',
    precuation_score: scored.score,
    scoring_audit: scored,

    structural_analysis_version: r.STRUCTURAL_ANALYSIS_VERSION || '',
    geometry_mode: r.GEOMETRY_MODE || '',
    body_region: r.BODY_REGION || '',
    body_subregion: r.BODY_SUBREGION || '',
    view_angle: r.VIEW_ANGLE || '',
    body_pose: r.BODY_POSE || '',
    tattoo_orientation: r.TATTOO_ORIENTATION || '',
    tattoo_style_tags: r.TATTOO_STYLE_TAGS || '',
    tattoo_subject_primary: r.TATTOO_SUBJECT_PRIMARY || '',
    tattoo_subject_tags: r.TATTOO_SUBJECT_TAGS || '',
    tattoo_stage_structural: r.TATTOO_STAGE_STRUCTURAL || '',
    tattoo_coverage: r.TATTOO_COVERAGE || '',
    composition_shape: r.COMPOSITION_SHAPE || '',
    focal_description: r.FOCAL_DESCRIPTION || '',
    crop_guidance_json: r.CROP_GUIDANCE_JSON || '',
    format_fit_json: r.FORMAT_FIT_JSON || '',
    best_formats: r.BEST_FORMATS || '',
    structural_confidence: Number(r.STRUCTURAL_CONFIDENCE || 0),
    structural_available: structuralAvailable,

    _analyzed_at: r.ANALYZED_AT || '',
    _curation_status: r.CURATION_STATUS || ''
  });
}

const out = [];

for (const [pid, allMedia] of Object.entries(grouped)) {
  const state = projectState.get(pid) || {};

  const projectAlreadyCurated = upper(state.CURATION_STATUS) === 'AI_CURATED';

  // Version mismatch by itself is intentionally NOT a reason to spend API again.
  const mediaNeedsCuration = allMedia.some(m => upper(m._curation_status) !== 'AI_CURATED');

  const latestAnalysisMs = Math.max(0, ...allMedia.map(m => ts(m._analyzed_at)));
  const projectCuratedMs = ts(state.CURATED_AT);
  const staleByTime =
    latestAnalysisMs > 0 &&
    (projectCuratedMs === 0 || latestAnalysisMs > projectCuratedMs);

  const needsCuration = !projectAlreadyCurated || mediaNeedsCuration || staleByTime;
  if (!needsCuration) continue;

  allMedia.sort((a, b) =>
    b.precuation_score - a.precuation_score ||
    b.analysis_confidence - a.analysis_confidence ||
    String(a.media_id).localeCompare(String(b.media_id))
  );

  const shortlist = allMedia.slice(0, Math.min(12, allMedia.length)).map(m => {
    const {_analyzed_at, _curation_status, ...clean} = m;
    return clean;
  });

  out.push({
    json: {
      no_work: false,
      project_id: pid,
      candidate_count: shortlist.length,
      candidates: shortlist,
      scoring_version: '2.0',
      curation_version: CURATION_VERSION,
      structural_candidates: shortlist.filter(x => x.structural_available).length,
      context:
        'Curadoria editorial de tattoo. Evitar quase-duplicatas. Usar Structural Vision quando disponível para anatomia, assunto, orientação e adequação de formato, sem inventar dados ausentes.',
      recuration_reason: {
        project_already_curated: projectAlreadyCurated,
        media_needs_curation: mediaNeedsCuration,
        stale_by_time: staleByTime,
        latest_analysis_at: latestAnalysisMs ? new Date(latestAnalysisMs).toISOString() : '',
        previous_curated_at: state.CURATED_AT || ''
      },
      config_contract: {
        pipeline: config['pipeline.contract_version'] || '',
        scoring_source: config['scoring.source'] || '',
        structural_policy: config['vision.structural_required_for_curation'] || 'PREFER_WITH_FALLBACK'
      }
    }
  });
}

if (out.length === 0) {
  return [{
    json: {
      no_work: true,
      status: 'CURATION_UP_TO_DATE',
      message: 'Nenhum projeto precisa de nova curadoria.',
      checked_at: new Date().toISOString()
    }
  }];
}

return out;

// PROJETO SM3 — BUILD REAL CURATION WRITES
// Machine curation only. This does NOT mean human approval.
// DISCARD is editorial status only; nothing is deleted.

const items = $input.all().map(i => i.json);
const now = new Date().toISOString();

return items.map(x => {
  const c = x.curation || {};
  const allowed = new Set(x.candidate_ids || []);

  const hero = String(c.hero_id || '');
  const selected = Array.isArray(c.selected_ids) ? c.selected_ids : [];
  const reserve = Array.isArray(c.reserve_ids) ? c.reserve_ids : [];
  const discard = Array.isArray(c.discard_ids) ? c.discard_ids : [];
  const carousel = Array.isArray(c.carousel_order) ? c.carousel_order : [];
  const reel = Array.isArray(c.reel_candidate_ids) ? c.reel_candidate_ids : [];
  const groups = Array.isArray(c.redundancy_groups) ? c.redundancy_groups : [];

  if (!hero || !allowed.has(hero)) {
    throw new Error(`CURATION_WRITE_BLOCK: invalid hero for ${x.project_id}`);
  }

  const covered = new Set([...selected, ...reserve, ...discard]);
  if (covered.size !== allowed.size || [...allowed].some(id => !covered.has(id))) {
    throw new Error(`CURATION_WRITE_BLOCK: buckets do not cover all candidates for ${x.project_id}`);
  }

  const overlaps =
    selected.filter(id => reserve.includes(id) || discard.includes(id)).length +
    reserve.filter(id => discard.includes(id)).length;

  if (overlaps > 0) {
    throw new Error(`CURATION_WRITE_BLOCK: overlapping curation buckets for ${x.project_id}`);
  }

  if (!selected.includes(hero)) {
    throw new Error(`CURATION_WRITE_BLOCK: hero is not selected for ${x.project_id}`);
  }

  const rankOrder = [
    hero,
    ...selected.filter(id => id !== hero),
    ...reserve,
    ...discard
  ];

  const redundancyById = new Map();

  groups.forEach((g, idx) => {
    const groupId = `RG${String(idx + 1).padStart(2, '0')}`;
    const members = Array.isArray(g.member_ids) ? g.member_ids : [];
    const preferred = String(g.preferred_id || '');
    const reason = String(g.reason || '').trim();

    if (preferred && !members.includes(preferred)) {
      throw new Error(`CURATION_WRITE_BLOCK: preferred redundancy ID not in group ${groupId}`);
    }

    for (const id of members) {
      if (!allowed.has(id)) {
        throw new Error(`CURATION_WRITE_BLOCK: unknown redundancy ID ${id}`);
      }
      if (redundancyById.has(id)) {
        throw new Error(`CURATION_WRITE_BLOCK: ${id} appears in more than one redundancy group`);
      }
      redundancyById.set(id, {
        group: groupId,
        preferred: id === preferred ? 'TRUE' : 'FALSE',
        reason
      });
    }
  });

  const mediaWrites = [...allowed].map(id => {
    const role =
      id === hero ? 'HERO' :
      selected.includes(id) ? 'SELECTED' :
      reserve.includes(id) ? 'RESERVE' :
      'DISCARD';

    const redundancy = redundancyById.get(id) || {
      group: '',
      preferred: '',
      reason: ''
    };

    const carouselPos = carousel.indexOf(id);
    const rankPos = rankOrder.indexOf(id);

    return {
      ID_MIDIA: id,
      CURATION_STATUS: 'AI_CURATED',
      CURATION_VERSION: 'SM3_CURATION_V2_STRUCTURAL_CONFIG',
      CURATION_ROLE: role,
      CURATION_RANK: rankPos >= 0 ? rankPos + 1 : '',
      REDUNDANCY_GROUP: redundancy.group,
      REDUNDANCY_PREFERRED: redundancy.preferred,
      REDUNDANCY_REASON: redundancy.reason,
      CAROUSEL_POSITION: carouselPos >= 0 ? carouselPos + 1 : '',
      REEL_CANDIDATE: reel.includes(id) ? 'TRUE' : 'FALSE',
      CURATED_AT: now,
      CURATION_PROVIDER: x.provider || '',
      CURATION_MODEL: x.model || '',
      CURATION_CONFIDENCE: Number(c.confidence ?? ''),
      CURATION_RUN_ID: x.response_id || ''
    };
  });

  const projectWrite = {
    ID_PROJETO: x.project_id,
    CURATION_STATUS: 'AI_CURATED',
    CURATION_VERSION: 'SM3_CURATION_V2_STRUCTURAL_CONFIG',
    CURATION_HERO_ID: hero,
    CURATION_SELECTED_IDS: selected.join(', '),
    CURATION_RESERVE_IDS: reserve.join(', '),
    CURATION_DISCARD_IDS: discard.join(', '),
    CURATION_CAROUSEL_ORDER: carousel.join(', '),
    CURATION_REEL_IDS: reel.join(', '),
    CURATION_NARRATIVE: String(c.narrative || '').trim(),
    CURATION_CONFIDENCE: Number(c.confidence ?? ''),
    CURATED_AT: now,
    CURATION_PROVIDER: x.provider || '',
    CURATION_MODEL: x.model || '',
    CURATION_RUN_ID: x.response_id || ''
  };

  return {
    json: {
      project_id: x.project_id,
      project_write: projectWrite,
      media_writes: mediaWrites,
      write_summary: {
        hero_id: hero,
        selected: selected.length,
        reserve: reserve.length,
        discard: discard.length,
        media_rows: mediaWrites.length,
        redundancy_groups: groups.length,
        carousel_items: carousel.length,
        reel_candidates: reel.length
      }
    }
  };
});

const out = [];
for (const item of $input.all()) {
  for (const row of (item.json.media_writes || [])) {
    out.push({json: row});
  }
}
return out;

const items = $input.all().map(i => i.json);

const noWork = items.some(x =>
  x.status === 'CURATION_UP_TO_DATE' ||
  x.status === 'NO_WORK' ||
  x.completed === true
);

return [{
  json: {
    workflow: 'PROJETO_SM3_03_CURATION',
    status: noWork ? 'NO_CHANGES' : 'CURATION_WRITTEN',
    message: noWork
      ? 'Curadoria já estava atualizada; nenhuma chamada de Vision ou escrita foi necessária.'
      : 'Curadoria concluída e persistida em 03_MIDIAS e 01_PROJETOS.',
    completed_at: new Date().toISOString()
  }
}];
